const record = $input.first().json || {};
const nonBlank = (value) => typeof value === 'string' && value.trim().length > 0;
let payload = record.message;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch { payload = null; }
}
const exactKeys = ['action_id', 'error_code', 'request_hash', 'status'];
const keysOk = payload && typeof payload === 'object' && !Array.isArray(payload) && Object.keys(payload).sort().join('\u0000') === exactKeys.join('\u0000');
const statusOk = payload && (payload.status === 'SENT' || payload.status === 'FAILED');
const errorOk = payload && (payload.status === 'SENT' ? payload.error_code === null : nonBlank(payload.error_code));
// n8n Kafka Trigger(onlyMessage=false)는 실측상 `message`·`topic`만 내보낸다. partition·offset·key는
// 있으면 검증하고 없으면 null로 둔다(있는데 형식이 틀리면 거부).
const hasPartition = record.partition !== undefined && record.partition !== null;
const hasOffset = record.offset !== undefined && record.offset !== null && String(record.offset) !== '';
const hasKey = record.key !== undefined && record.key !== null;
const partitionOk = !hasPartition || (Number.isInteger(record.partition) && record.partition >= 0);
const offsetOk = !hasOffset || /^\d+$/.test(String(record.offset));
const keyOk = !hasKey || nonBlank(record.key);
const metadataOk = record.topic === 'fdc.actions.result' && partitionOk && offsetOk && keyOk;
const identityOk = payload && nonBlank(payload.action_id) && (!hasKey || record.key === payload.action_id) && /^([0-9a-f]{64})$/.test(payload.request_hash);
const valid = keysOk && statusOk && errorOk && metadataOk && identityOk;
let reasonCode = null;
if (!keysOk || !statusOk || !errorOk) reasonCode = 'RESULT_PAYLOAD_INVALID';
else if (!metadataOk) reasonCode = 'RESULT_METADATA_INVALID';
else if (!identityOk) reasonCode = 'RESULT_IDENTITY_MISMATCH';
return [{ json: { valid, payload: valid ? payload : null, metadata: { topic: record.topic ?? null, partition: hasPartition && partitionOk ? record.partition : null, offset: hasOffset && offsetOk ? String(record.offset) : null }, evidence: { action_id: payload && nonBlank(payload.action_id) ? payload.action_id : null, request_hash: payload && /^([0-9a-f]{64})$/.test(payload.request_hash) ? payload.request_hash : null, reason_code: reasonCode } } }];

const crypto = require('crypto');
const item = $input.first().json;
const payload = item.payload;
const metadata = item.metadata;
const secret = String($env.N8N_WEBHOOK_SECRET ?? '').trim();
const rawBaseUrl = String($env.BACKEND_BASE_URL ?? '').trim();
let baseUrl = null;
// n8n Code node 샌드박스(JS Task Runner)에는 URL 전역이 없다 — 정규식으로만 검증한다.
const baseMatch = /^https?:\/\/([^\s\/?#]+)[^\s]*$/i.exec(rawBaseUrl);
if (baseMatch && !baseMatch[1].includes('@')) baseUrl = rawBaseUrl.replace(/\/+$/, '');
if (!secret || !baseUrl) return [{ json: { config_ok: false } }];
const timestamp = String(Math.floor(Date.now() / 1000));
const callback = {
  event_id: `WF4:${payload.action_id}:MES_MOCK:${payload.request_hash}:${payload.status}`,
  channel: 'MES_MOCK',
  status: payload.status,
  provider_message_id: payload.status === 'SENT' ? (metadata.partition !== null && metadata.offset !== null ? `kafka:${metadata.topic}:${metadata.partition}:${metadata.offset}` : `kafka:${metadata.topic}:${payload.action_id}:${payload.request_hash}`) : null,
  request_hash: payload.request_hash,
  completed_at: new Date().toISOString(),
  error_code: payload.status === 'SENT' ? null : 'MES_MOCK_FAILED'
};
const callbackRawBody = JSON.stringify(callback);
const signature = `sha256=${crypto.createHmac('sha256', secret).update(`${timestamp}.${callbackRawBody}`, 'utf8').digest('hex')}`;
return [{ json: { config_ok: true, callback_raw_body: callbackRawBody, callback_url: `${baseUrl}/internal/actions/${encodeURIComponent(payload.action_id)}/delivery`, callback_timestamp: timestamp, callback_signature: signature } }];

const result = $input.first().json || {};
const statusCode = Number(result.statusCode);
if (Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300) return [{ json: { callback_ok: true, status_code: statusCode } }];
if (statusCode === 401) throw new Error('CALLBACK_UNAUTHORIZED');
if (Number.isInteger(statusCode) && statusCode >= 400 && statusCode < 500) throw new Error(`CALLBACK_REJECTED_${statusCode}`);
throw new Error(`CALLBACK_FAILED_${Number.isInteger(statusCode) ? statusCode : 'TRANSPORT'}`);
